import json, sys

data = json.load(sys.stdin)
with open('after-cpm-packages.json', 'w') as f:
    json.dump(data, f, indent=2)

with open('baseline-packages.json') as f:
    baseline = json.load(f)

# Build lookup: (project, tfm, pkg) -> resolved version
def build_lookup(d):
    lk = {}
    for proj in d.get('projects', []):
        pname = proj['path'].split('/')[-1]
        for fw in proj.get('frameworks', []):
            tfm = fw['framework']
            for pkg in fw.get('topLevelPackages', []):
                lk[(pname, tfm, pkg['id'])] = (pkg['requestedVersion'], pkg['resolvedVersion'])
    return lk

bl = build_lookup(baseline)
al = build_lookup(data)

changes = []
unchanged = []
all_keys = sorted(set(bl.keys()) | set(al.keys()))
for k in all_keys:
    proj, tfm, pkg = k
    if k in bl and k in al:
        b_req, b_res = bl[k]
        a_req, a_res = al[k]
        if b_res != a_res:
            changes.append((proj, tfm, pkg, b_res, a_res, 'Aligned to highest version'))
        else:
            unchanged.append((proj, tfm, pkg, a_res))
    elif k in bl and k not in al:
        b_req, b_res = bl[k]
        changes.append((proj, tfm, pkg, b_res, 'REMOVED', 'Removed'))
    elif k not in bl and k in al:
        a_req, a_res = al[k]
        changes.append((proj, tfm, pkg, 'N/A', a_res, 'Added'))

print('=== CHANGES ===')
if changes:
    for c in changes:
        print(f'  {c[0]:20} {c[1]:10} {c[2]:50} {c[3]:10} -> {c[4]:10} ({c[5]})')
else:
    print('  None')

print()
print('=== UNCHANGED ===')
for u in unchanged:
    print(f'  {u[0]:20} {u[1]:10} {u[2]:50} {u[3]}')
"

